-- Test COALESCE with various argument counts
SELECT COALESCE(NULL, 'first non-null') AS two_args;
SELECT COALESCE(NULL, NULL, NULL, 'found') AS four_args;
SELECT COALESCE('immediate', NULL, 'later') AS first_is_nonnull;
SELECT COALESCE(NULL, NULL, NULL) AS all_nulls;

-- Test COALESCE with different types
SELECT 
  x, y, z,
  COALESCE(x, y, z, 0) AS result
FROM (VALUES 
  (1, NULL, NULL),
  (NULL, 2, NULL),
  (NULL, NULL, 3),
  (NULL, NULL, NULL)
) AS t(x, y, z);

-- Test COALESCE with expressions
SELECT 
  a, b,
  COALESCE(a * 2, b + 10, 100) AS computed
FROM (VALUES 
  (5, NULL),
  (NULL, 3),
  (NULL, NULL)
) AS t(a, b);

-- Test NULLIF basic behavior
SELECT NULLIF(5, 5) AS equal_values;
SELECT NULLIF(5, 10) AS different_values;
SELECT NULLIF('hello', 'hello') AS equal_strings;
SELECT NULLIF('hello', 'world') AS different_strings;

-- Test NULLIF with NULL inputs
SELECT NULLIF(NULL, 5) AS first_null;
SELECT NULLIF(5, NULL) AS second_null;
SELECT NULLIF(NULL, NULL) AS both_null;

-- Test NULLIF in practical scenarios (avoiding division by zero)
SELECT 
  a, b,
  a / NULLIF(b, 0) AS safe_division
FROM (VALUES 
  (10, 2),
  (15, 0),
  (20, 5),
  (8, 0)
) AS t(a, b);

-- Test NULLIF with expressions
SELECT 
  x,
  NULLIF(x * 2, 10) AS nullif_expr,
  NULLIF(CAST(x AS VARCHAR), '3') AS nullif_cast
FROM (VALUES (1), (3), (5), (7)) AS t(x);

-- Test GREATEST with multiple arguments
SELECT GREATEST(1, 5, 3, 9, 2) AS max_of_five;
SELECT GREATEST(1) AS single_arg;
SELECT GREATEST(-10, -5, -20, -1) AS negative_numbers;

-- Test LEAST with multiple arguments
SELECT LEAST(10, 2, 8, 4, 15) AS min_of_five;
SELECT LEAST(100) AS single_arg;
SELECT LEAST(-10, -5, -20, -1) AS negative_numbers;

-- Test with NULL values
SELECT GREATEST(1, NULL, 5, 3) AS greatest_with_null;
SELECT LEAST(10, 2, NULL, 8) AS least_with_null;
SELECT GREATEST(NULL, NULL) AS all_nulls_greatest;
SELECT LEAST(NULL, NULL) AS all_nulls_least;

-- Test with different numeric types
SELECT 
  GREATEST(1, 2.5, 3::BIGINT) AS mixed_types_greatest,
  LEAST(10, 5.5, 3::BIGINT) AS mixed_types_least;

-- Test with strings
SELECT GREATEST('apple', 'zebra', 'banana', 'cherry') AS string_greatest;
SELECT LEAST('apple', 'zebra', 'banana', 'cherry') AS string_least;

-- Test in table context
SELECT 
  a, b, c,
  GREATEST(a, b, c) AS max_value,
  LEAST(a, b, c) AS min_value
FROM (VALUES 
  (5, 10, 3),
  (8, 2, 12),
  (7, 7, 7),
  (1, 100, 50)
) AS t(a, b, c);

-- Test IF function (should be translated to CASE)
SELECT IF(1 > 0, 'true', 'false') AS if_true;
SELECT IF(1 < 0, 'true', 'false') AS if_false;

-- Test IF with NULL condition
SELECT IF(NULL, 'true', 'false') AS if_null_condition;

-- Test IF with NULL branches
SELECT 
  x,
  IF(x > 0, 'positive', NULL) AS if_with_null_else
FROM (VALUES (-1), (0), (5)) AS t(x);

-- Test IF with expressions
SELECT 
  a, b,
  IF(a > b, a * 2, b * 3) AS if_expr
