CREATE TABLE discounts (id INT, min_price DECIMAL(10,2), discount_pct INT);
INSERT INTO discounts VALUES (1, 0.00, 0), (2, 10.00, 10), (3, 20.00, 15);

SELECT p.name, p.price, d.discount_pct, ROUND(p.price * (100 - d.discount_pct) / 100, 2) AS final_price
FROM products p
JOIN discounts d ON p.price >= d.min_price
WHERE d.discount_pct = (
  SELECT MAX(d2.discount_pct)
  FROM discounts d2
  WHERE p.price >= d2.min_price
)
ORDER BY p.id;

