WITH RECURSIVE series AS (
  SELECT 1 as n
  UNION ALL
  SELECT n + 1 FROM series WHERE n < 5
)
SELECT * FROM series ORDER BY n;

WITH RECURSIVE factorial AS (
  SELECT 1 as n, 1 as fact
  UNION ALL
  SELECT n + 1, fact * (n + 1) FROM factorial WHERE n < 7
)
SELECT n, fact FROM factorial ORDER BY n;

WITH RECURSIVE running_sum AS (
  SELECT 1 as n, 1 as sum_n
  UNION ALL
  SELECT n + 1, sum_n + (n + 1) FROM running_sum WHERE n < 10
)
SELECT n, sum_n FROM running_sum ORDER BY n;

WITH RECURSIVE empty_recur AS (
  SELECT 1 as n, 'anchor' as label
  UNION ALL
  SELECT n + 1, 'recursive' FROM empty_recur WHERE FALSE
)
SELECT * FROM empty_recur;

CREATE TABLE categories (id INTEGER, name VARCHAR, weight INTEGER);
INSERT INTO categories VALUES (1, 'A', 10), (2, 'B', 20), (3, 'C', 15);

WITH RECURSIVE weighted_series AS (
  SELECT 1 as n, c.name, c.weight
  FROM categories c
  WHERE c.id = 1
  UNION ALL
  SELECT ws.n + 1, c.name, ws.weight + c.weight
  FROM weighted_series ws
  JOIN categories c ON c.id = ws.n + 1
)
SELECT * FROM weighted_series ORDER BY n;

CREATE TABLE graph (from_id INTEGER, to_id INTEGER);
INSERT INTO graph VALUES 
  (1, 2), (2, 3), (3, 4), (4, 2), (2, 5);

WITH RECURSIVE traversal AS (
  SELECT 1 as current, ARRAY[1] as path, 0 as depth
  UNION ALL
  SELECT g.to_id, list_append(t.path, g.to_id), t.depth + 1
  FROM traversal t
  JOIN graph g ON t.current = g.from_id
  WHERE NOT list_contains(t.path, g.to_id) AND t.depth < 10
)
SELECT current, len(path) as path_len, depth FROM traversal ORDER BY depth, current;

