WITH RECURSIVE descendants AS (
  SELECT 1 as root, 1 as node, 0 as depth
  UNION ALL
  SELECT d.root, pc.child, d.depth + 1
  FROM descendants d
  JOIN parent_child pc ON d.node = pc.parent
  WHERE d.depth < 3
)
SELECT root, node, depth FROM descendants ORDER BY depth, node;

